/**
 * @file utest_ipmi_fru_parser.cpp
 *
 * Unit tests for IpmiFruParser.
 *
 * Binary fixtures are generated by gen_ipmi_fru_fixtures.py and stored in
 * test/vpd_files/.  All checksums in those files are correct per the IPMI
 * Platform Management FRU Information Storage Definition v1.0 Rev 1.3 spec.
 *
 * Test categories:
 *   1. Common Header validation (version, checksum, size)
 *   2. Product Info Area parsing (8-bit ASCII fields, empty field)
 *   3. Board Info Area parsing (timestamp, all fields, custom fields)
 *   4. Chassis Info Area parsing (type byte, predefined + custom fields)
 *   5. MultiRecord Area parsing (type ID, data bytes, multi-record chaining)
 *   6. All-areas image (Internal + Chassis + Board + Product + MultiRecord)
 *   7. 6-bit packed ASCII decoding
 *   8. Bad checksum rejection (header, board area, product area, multirecord
 * hdr)
 *   9. Structural errors (truncated buffer, field length overflow)
 *  10. readKeywordFromHardware (hit, miss, wrong param type)
 *  11. writeKeywordOnHardware (in-memory update + checksum recalc, clamping,
 *                              no-file-path error, no-open-stream error,
 *                              empty keyword/value errors)
 *  12. Empty input vector
 */

#include "exceptions.hpp"
#include "ipmi_fru_parser.hpp"
#include "types.hpp"

#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <numeric>

#include <gtest/gtest.h>

using namespace vpd;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Read an entire binary file into a BinaryVector. */
static types::BinaryVector readFile(const std::string& i_path)
{
    std::ifstream l_f(i_path, std::ios::binary);
    if (!l_f.is_open())
    {
        throw std::runtime_error("Cannot open fixture: " + i_path);
    }
    return types::BinaryVector(std::istreambuf_iterator<char>(l_f),
                               std::istreambuf_iterator<char>());
}

/** Extract a BinaryVector from the parsed KeywordVpdMap. Asserts the key
 * exists. */
static types::BinaryVector getVec(const types::KeywordVpdMap& i_map,
                                  const std::string& i_key)
{
    auto l_it = i_map.find(i_key);
    if (l_it == i_map.end())
    {
        ADD_FAILURE() << "Key not found in parsed map: " << i_key;
        return {};
    }
    if (auto* l_v = std::get_if<types::BinaryVector>(&l_it->second))
    {
        return *l_v;
    }
    ADD_FAILURE() << "Value for key '" << i_key << "' is not a BinaryVector";
    return {};
}

/** Convert a BinaryVector to its string representation. */
static std::string vecToStr(const types::BinaryVector& i_vec)
{
    return std::string(i_vec.begin(), i_vec.end());
}

/** Recompute zero-sum checksum over [data[0] .. data[n-2]] and return it. */
[[maybe_unused]] static uint8_t computeChecksum(
    const types::BinaryVector& i_data, size_t i_start, size_t i_onePastLast)
{
    uint8_t l_sum = 0;
    for (size_t i = i_start; i < i_onePastLast; ++i)
    {
        l_sum = static_cast<uint8_t>(l_sum + i_data[i]);
    }
    return static_cast<uint8_t>(~l_sum + 1);
}

// ---------------------------------------------------------------------------
// Suite 1: Common Header validation
// ---------------------------------------------------------------------------

/** Parsing a buffer smaller than 8 bytes must throw DataException. */
TEST(IpmiFruParserHdr, TruncatedBufferThrows)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_truncated.dat");
    IpmiFruParser l_parser(l_vec);
    EXPECT_THROW(l_parser.parse(), DataException);
}

/** Empty input vector must throw DataException. */
TEST(IpmiFruParserHdr, EmptyVectorThrows)
{
    IpmiFruParser l_parser(types::BinaryVector{});
    EXPECT_THROW(l_parser.parse(), DataException);
}

/** Corrupted Common Header checksum must throw DataException. */
TEST(IpmiFruParserHdr, BadHeaderChecksumThrows)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_bad_hdr_checksum.dat");
    IpmiFruParser l_parser(l_vec);
    EXPECT_THROW(l_parser.parse(), DataException);
}

/** Wrong format version in Common Header byte[0] must throw DataException. */
TEST(IpmiFruParserHdr, BadFormatVersionThrows)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_bad_format_version.dat");
    IpmiFruParser l_parser(l_vec);
    EXPECT_THROW(l_parser.parse(), DataException);
}

/** Valid 8-byte header with no areas returns an empty KeywordVpdMap. */
TEST(IpmiFruParserHdr, HeaderOnlyNoAreasReturnsEmptyMap)
{
    // Build a minimal valid 8-byte header with all area offsets = 0.
    types::BinaryVector l_hdr = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t l_cs = static_cast<uint8_t>(
        ~std::accumulate(l_hdr.begin(), l_hdr.end(), uint8_t{0}) + 1);
    l_hdr.push_back(l_cs);

    IpmiFruParser l_parser(l_hdr);
    auto l_result = l_parser.parse();
    auto* l_map = std::get_if<types::KeywordVpdMap>(&l_result);
    ASSERT_NE(l_map, nullptr);
    EXPECT_TRUE(l_map->empty());
}

