// ---------------------------------------------------------------------------
// Suite 5: MultiRecord-only image
// ---------------------------------------------------------------------------

TEST(IpmiFruMultiRecord, ThreeRecordsChainingParsed)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_multirecord_only.dat");
    IpmiFruParser l_parser(std::move(l_vec));
    auto l_variant = l_parser.parse();
    auto* l_map = std::get_if<types::KeywordVpdMap>(&l_variant);
    ASSERT_NE(l_map, nullptr);

    // Record 1: typeId=0xC0, data={0x10,0x20,0x30}
    auto l_t1 = getVec(*l_map, "MULTIRECORD_1_TypeId");
    ASSERT_EQ(l_t1.size(), 1u);
    EXPECT_EQ(l_t1[0], 0xC0);
    auto l_d1 = getVec(*l_map, "MULTIRECORD_1");
    ASSERT_EQ(l_d1.size(), 3u);
    EXPECT_EQ(l_d1[0], 0x10);

    // Record 2: typeId=0xC1
    auto l_t2 = getVec(*l_map, "MULTIRECORD_2_TypeId");
    ASSERT_EQ(l_t2.size(), 1u);
    EXPECT_EQ(l_t2[0], 0xC1);

    // Record 3: typeId=0xC2, zero-length data, End-of-list
    auto l_t3 = getVec(*l_map, "MULTIRECORD_3_TypeId");
    ASSERT_EQ(l_t3.size(), 1u);
    EXPECT_EQ(l_t3[0], 0xC2);
    auto l_d3 = getVec(*l_map, "MULTIRECORD_3");
    EXPECT_TRUE(l_d3.empty());

    // No Record 4 should exist.
    EXPECT_EQ(l_map->find("MULTIRECORD_4_TypeId"), l_map->end());
}

