TEST(IpmiFruReadKw, ExistingKeyReturnsCorrectBytes)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_product_only.dat");
    IpmiFruParser l_parser(std::move(l_vec));
    l_parser.parse();

    types::ReadVpdParams l_params = types::Keyword{"PRODUCT_SerialNumber"};
    auto l_result = l_parser.readKeywordFromHardware(l_params);

    auto* l_bv = std::get_if<types::BinaryVector>(&l_result);
    ASSERT_NE(l_bv, nullptr);
    EXPECT_EQ(std::string(l_bv->begin(), l_bv->end()), "S6ERNX0T123456");
}

