// ---------------------------------------------------------------------------
// Suite 10: writeKeywordOnHardware — successful write with checksum update
// ---------------------------------------------------------------------------

/**
 * Copy the writeable_product fixture to a real tmpfile, open an
 * IpmiFruParser on it, write a new serial number, then re-parse the
 * file from disk and verify the new value and valid area checksum.
 */
TEST(IpmiFruWriteKw, WriteUpdatesFileAndChecksum)
{
    // Step 1 — copy fixture to a temporary file.
    const std::string l_src = "vpd_files/ipmi_fru_writeable_product.dat";
    const std::string l_tmp = std::tmpnam(nullptr); // NOLINT
    {
        std::ifstream l_in(l_src, std::ios::binary);
        ASSERT_TRUE(l_in.is_open()) << "Cannot open " << l_src;
        std::ofstream l_out(l_tmp, std::ios::binary | std::ios::trunc);
        ASSERT_TRUE(l_out.is_open()) << "Cannot create tmpfile " << l_tmp;
        l_out << l_in.rdbuf();
    }

    // Step 2 — parse and write new serial number.
    {
        auto l_vec = readFile(l_tmp);
        IpmiFruParser l_parser(std::move(l_vec), l_tmp);
        l_parser.parse();

        const std::string l_newSerial = "NEWSERIAL001";
        types::WriteVpdParams l_params = types::KwData{
            "PRODUCT_SerialNumber",
            types::BinaryVector(l_newSerial.begin(), l_newSerial.end())};
        int l_written = l_parser.writeKeywordOnHardware(l_params);
        EXPECT_EQ(l_written, static_cast<int>(l_newSerial.size()));
    }

    // Step 3 — re-read the file from disk and re-parse.
    auto l_updated = readFile(l_tmp);
    IpmiFruParser l_parser2(l_updated);
    auto l_variant = l_parser2.parse();
    auto* l_map = std::get_if<types::KeywordVpdMap>(&l_variant);
    ASSERT_NE(l_map, nullptr);

    // Step 4 — verify serial number value was updated.
    EXPECT_EQ(vecToStr(getVec(*l_map, "PRODUCT_SerialNumber")), "NEWSERIAL001");

    // Step 5 — verify the product area checksum is still valid in the file.
    const size_t l_prodOffset =
        l_updated[4] * 8u; // byte[4] = product offset units
    const size_t l_prodLen = l_updated[l_prodOffset + 1] * 8u;
    uint8_t l_sum = 0;
    for (size_t i = l_prodOffset; i < l_prodOffset + l_prodLen; ++i)
    {
        l_sum = static_cast<uint8_t>(l_sum + l_updated[i]);
    }
    EXPECT_EQ(l_sum, 0u) << "Product area checksum is invalid after write";

    std::remove(l_tmp.c_str());
}

/**
 * If the new value is shorter than the field capacity, only the written
 * bytes are changed; the remainder of the field in memory keeps the old bytes.
 * The count returned must equal the length of the new value, not the capacity.
 */
TEST(IpmiFruWriteKw, WriteClampedToCapacity)
{
    const std::string l_src = "vpd_files/ipmi_fru_writeable_product.dat";
    const std::string l_tmp = std::tmpnam(nullptr); // NOLINT
    {
        std::ifstream l_in(l_src, std::ios::binary);
        ASSERT_TRUE(l_in.is_open());
        std::ofstream l_out(l_tmp, std::ios::binary | std::ios::trunc);
        l_out << l_in.rdbuf();
    }

    auto l_vec = readFile(l_tmp);
    IpmiFruParser l_parser(std::move(l_vec), l_tmp);
    l_parser.parse();

    // Write only 5 bytes into a 12-byte serial number field.
    const std::string l_shortSN = "SHORT";
    types::WriteVpdParams l_params =
        types::KwData{"PRODUCT_SerialNumber",
                      types::BinaryVector(l_shortSN.begin(), l_shortSN.end())};
    int l_written = l_parser.writeKeywordOnHardware(l_params);
    EXPECT_EQ(l_written, 5);

    std::remove(l_tmp.c_str());
}

/**
 * Writing more bytes than the field capacity: the write must be silently
 * clamped to the field capacity and return that clamped count.
 */
TEST(IpmiFruWriteKw, WriteExceedingCapacityIsClamped)
{
    const std::string l_src = "vpd_files/ipmi_fru_writeable_product.dat";
    const std::string l_tmp = std::tmpnam(nullptr); // NOLINT
    {
        std::ifstream l_in(l_src, std::ios::binary);
        ASSERT_TRUE(l_in.is_open());
        std::ofstream l_out(l_tmp, std::ios::binary | std::ios::trunc);
        l_out << l_in.rdbuf();
    }

    auto l_vec = readFile(l_tmp);
    IpmiFruParser l_parser(std::move(l_vec), l_tmp);
    l_parser.parse();

    // Serial field capacity is 12 bytes; try to write 20.
    types::BinaryVector l_longVal(20, 'Z');
    types::WriteVpdParams l_params =
        types::KwData{"PRODUCT_SerialNumber", l_longVal};
    int l_written = l_parser.writeKeywordOnHardware(l_params);
    EXPECT_EQ(l_written, 12);

    std::remove(l_tmp.c_str());
}

/**
 * Writing to a keyword that does not exist in the parsed map must throw.
 */
TEST(IpmiFruWriteKw, UnknownKeywordThrowsDataException)
{
    const std::string l_src = "vpd_files/ipmi_fru_writeable_product.dat";
    const std::string l_tmp = std::tmpnam(nullptr); // NOLINT
    {
        std::ifstream l_in(l_src, std::ios::binary);
        ASSERT_TRUE(l_in.is_open());
        std::ofstream l_out(l_tmp, std::ios::binary | std::ios::trunc);
        l_out << l_in.rdbuf();
    }

    auto l_vec = readFile(l_tmp);
    IpmiFruParser l_parser(std::move(l_vec), l_tmp);
    l_parser.parse();

    types::WriteVpdParams l_params =
        types::KwData{"BOARD_Manufacturer", types::BinaryVector{'I', 'B', 'M'}};
    EXPECT_THROW(l_parser.writeKeywordOnHardware(l_params), DataException);

    std::remove(l_tmp.c_str());
}

// ---------------------------------------------------------------------------
// Suite 11: parse() return type variant
// ---------------------------------------------------------------------------

/** The VPDMapVariant returned must hold KeywordVpdMap, not monostate or
 * IPZVpdMap. */
TEST(IpmiFruReturnType, VariantHoldsKeywordVpdMap)
{
    auto l_vec = readFile("vpd_files/ipmi_fru_product_only.dat");
    IpmiFruParser l_parser(std::move(l_vec));
    auto l_variant = l_parser.parse();

    EXPECT_FALSE(std::holds_alternative<std::monostate>(l_variant));
    EXPECT_FALSE(std::holds_alternative<types::IPZVpdMap>(l_variant));
    EXPECT_TRUE(std::holds_alternative<types::KeywordVpdMap>(l_variant));
}
